class URL {
 constructor(raw){
  if(typeof raw!=='string'||/[^\x21-\x7e]/.test(raw))throw new Error('Use canonical ASCII or punycode URLs with percent-encoded paths');
  const m=/^(https?):\/\/([^/]+)(\/.*)?$/i.exec(raw);
  if(!m)throw new Error('Only public HTTP(S) URLs are supported');
  if(m[2].includes('@'))throw new Error('Remove URL credentials');
  if(/[?#]/.test(raw))throw new Error('Remove URL query strings and fragments');
  const a=/^([A-Za-z0-9.-]+)(?::([0-9]+))?$/.exec(m[2]);
  if(!a)throw new Error('Use a public canonical ASCII hostname and standard port');
  const host=a[1].toLowerCase(),protocol=m[1].toLowerCase()+':',port=a[2]?Number(a[2]):null;
  if(!host.includes('.')||host.length>253||/^[0-9.]+$/.test(host)||host.split('.').some(s=>!s||s.length>63||!/^[a-z0-9](?:[a-z0-9-]*[a-z0-9])?$/.test(s)))throw new Error('Use a public canonical ASCII hostname, not an IP address');
  if(port!==null&&port!==(protocol==='https:'?443:80))throw new Error('Only the standard HTTP(S) port is supported');
  const path=m[3]||'/';
  if(path.includes('\\')||/%(?![0-9a-f]{2})/i.test(path))throw new Error('Use a canonical percent-encoded URL path');
  if(path.split('/').some(s=>['.','..'].includes(s.replace(/%2e/ig,'.'))))throw new Error('Use a canonical URL without dot path segments');
  this.protocol=protocol;this.hostname=host;this.username='';this.password='';this.search='';this.hash='';
  this.href=protocol+'//'+host+path;
 }
 toString(){return this.href;}
}

