if(existingRunId&&!/^[A-Za-z0-9]{17}$/.test(existingRunId))throw new Error('Invalid existing run id');
if(!existingRunId&&o.allowPaidRun!==true)throw new Error('A new paid run requires allowPaidRun: true. Resume an existing run to avoid another start.');
if(!Array.isArray(o.urls)||o.urls.length<1||o.urls.length>20)throw new Error('Supply1-20 public HTTP(S) URLs');
const urls=[...new Set(o.urls.map(raw=>{
 if(typeof raw!=='string')throw new Error('Use public HTTP(S) URL strings');
 const u=new URL(raw);
 if(!['http:','https:'].includes(u.protocol))throw new Error('Only public HTTP(S) URLs are allowed');
 if(u.username||u.password)throw new Error('Remove URL credentials');
 if(u.search||u.hash)throw new Error('Use canonical URLs without query strings or fragments');
 const h=u.hostname.toLowerCase(),parts=h.split('.').map(Number);
 if(h==='localhost'||h.endsWith('.localhost')||h.endsWith('.local')||h.includes(':')||h==='0.0.0.0'||h.startsWith('127.')||h.startsWith('10.')||h.startsWith('192.168.')||(parts[0]===172&&parts[1]>=16&&parts[1]<=31)||(parts[0]===169&&parts[1]===254))throw new Error('Only public URLs are supported');
 return u.toString();
}))];
if(!Number.isSafeInteger(o.maxResults)||o.maxResults<1||o.maxResults>20)throw new Error('maxResults must be1-20');
if(!Number.isFinite(o.maxTotalChargeUsd)||o.maxTotalChargeUsd<0.005||o.maxTotalChargeUsd>0.05)throw new Error('Set a run budget from0.005 to0.05 USD');
return [{json:{mode:'live',existingRunId,maxTotalChargeUsd:o.maxTotalChargeUsd,actorInput:{urls,maxResults:Math.min(o.maxResults,urls.length),scanScripts:true}}}];

