const TERMINAL = new Set(['SUCCEEDED', 'FAILED', 'ABORTED', 'TIMED-OUT']);

function normalizedUrls(value) {
    const parts = [];
    const push = (entry) => {
        if (typeof entry !== 'string') throw new Error('Every input URL must be a string or an object with a URL.');
        // Match the Actor's URL boundaries without changing a literal comma
        // inside a path/query/fragment or adding phantom retry targets.
        for (const line of entry.split(/\n+|,\s+(?=https?:\/\/)/i)) {
            const text = line.trim();
            const address = text.replace(/^https?:\/\//i, '');
            const rootUrlList = /^https?:\/\/[^/?#,\s]+\/?(?:,\s*https?:\/\/[^/?#,\s]+\/?)+$/i.test(text);
            const entries = rootUrlList || !/[/?#]/.test(address) ? text.split(/,+/) : [text];
            parts.push(...entries.map((s) => s.trim()).filter(Boolean));
        }
    };
    if (Array.isArray(value)) {
        for (const entry of value) push(entry && typeof entry === 'object' ? entry.url : entry);
    } else push(value);
    return [...new Set(parts.map((value) => {
        if (/^[a-z][\w+.-]*:\/\//i.test(value) && !/^https?:\/\//i.test(value)) throw new Error('Only HTTP(S) URLs are supported.');
        const url = new URL(/^https?:\/\//i.test(value) ? value : `https://${value}`);
        if (url.username || url.password) throw new Error('Remove credentials from input URLs before making a report.');
        return url.toString();
    }))];
}

function classify(row) {
    if (row.error === null && row.statusCode >= 200 && row.statusCode < 400) return 'successful';
    const message = row.error ?? '';
    // Do not propose automatic retries of access-control pages or source rate limits.
    if ([401, 403, 429].includes(row.statusCode) || /bot.check|captcha|certificate|DNS lookup failed|domain does not exist|ENOTFOUND|forbidden/i.test(message)) return 'needs-review';
    if ([408, 425, 500, 502, 503, 504].includes(row.statusCode) || /timed? ?out|did not respond within|ECONNRESET|EAI_AGAIN|temporary/i.test(message)) return 'transient-failure';
    return 'needs-review';
}

function csvCell(value) {
    let text = value === null || value === undefined ? '' : String(value);
    if (/^[\s\uFEFF]*[=+@-]/u.test(text)) text = `'${text}`;
    return `"${text.replaceAll('"', '""')}"`;
}

function prepareBatch(input, items, metadata) {
    if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('Use the original Actor input JSON object.');
    const urls = normalizedUrls(input.urls);
    if (!urls.length) throw new Error('The original input must contain at least one URL.');
    if (!Array.isArray(items)) throw new Error('Use a complete JSON array export of the default dataset.');
    const run = metadata?.data ?? metadata;
    if (!run || typeof run.id !== 'string' || !run.id.trim()) throw new Error('The saved run id is required.');
    if (!TERMINAL.has(run.status)) throw new Error('Finish the existing run first: retry preparation requires a terminal run status.');
    const requested = new Set(urls);
    const byUrl = new Map();
    for (const row of items) {
        if (!row || typeof row.url !== 'string' || !Object.hasOwn(row, 'error') || !(row.error === null || typeof row.error === 'string')) throw new Error('The error field is missing or invalid; use the complete JSON export, not a selected-field export.');
        if (!Object.hasOwn(row, 'statusCode') || !(row.statusCode === null || (Number.isInteger(row.statusCode) && row.statusCode >= 100 && row.statusCode <= 599)) || (row.statusCode === null && row.error === null)) throw new Error('Invalid statusCode: a missing HTTP status needs an explicit error.');
        const normalized = normalizedUrls([row.url])[0];
        if (!requested.has(normalized)) throw new Error('A dataset URL was not requested in the original input; check the run and export.');
        if (byUrl.has(normalized)) throw new Error('Duplicate dataset URL; verify the complete export before preparing any retry.');
        byUrl.set(normalized, { ...row, url: normalized, classification: classify(row) });
    }
    const rows = urls.filter((url) => byUrl.has(url)).map((url) => byUrl.get(url));
    const transient = rows.filter((r) => r.classification === 'transient-failure').map((r) => r.url);
    const unobservedUrls = urls.filter((url) => !byUrl.has(url));
    const warnings = [
        'This report does not contact Apify or any target website and never starts a run.',
        'Retry candidates require review. A new paid run has its own charges; there is no cross-run billing deduplication.',
        'A terminal run status does not prove that this export includes every dataset item. Download the complete JSON export without filters or limits.',
    ];
    if (unobservedUrls.length) warnings.push('An unobserved URL is not proof that it was never processed: an export limit, a run or charge cap, an abort, or another interruption may explain it. Inspect the original run before resubmitting it.');
    const retryCandidatesInput = transient.length ? { ...structuredClone(input), urls: transient, maxResults: transient.length } : null;
    const columns = ['url', 'classification', 'statusCode', 'error', 'technologyNames', 'analysisWarnings'];
    const csv = [columns.map(csvCell).join(','), ...rows.map((row) => [row.url, row.classification, row.statusCode, row.error, (row.technologyNames ?? []).join('; '), (row.analysisWarnings ?? []).join('; ')].map(csvCell).join(','))].join('\r\n') + '\r\n';
    return {
        run: { id: run.id, status: run.status },
        summary: {
            requested: urls.length,
            observed: rows.length,
            successful: rows.filter((r) => r.classification === 'successful').length,
            transientFailures: transient.length,
            needsReview: rows.filter((r) => r.classification === 'needs-review').length,
            unobserved: unobservedUrls.length,
        },
        rows, unobservedUrls, retryCandidatesInput, warnings, csv,
    };
}

const incoming=$input.first().json;
const context=incoming.demo===true?incoming:$('Check terminal run').first().json;
const items=incoming.demo===true?incoming.items:incoming.body;
if(!Array.isArray(items))throw new Error('Expected the complete dataset array in the HTTP response body');
if(items.length>context.input.urls.length)throw new Error('Dataset contains more rows than requested; verify this run/export');
const report=prepareBatch(context.input,items,context.run);
report.demo=incoming.demo===true;
if(report.demo)report.warnings.unshift('FICTIONAL DEMO: not website observations, customer use or income.');
return [{json:report}];

